// Validação do Webhook da Meta.
const query = $json.query || {};
const verifyTokenEsperado = 'cecape_n8n_whatsapp_2026';
const mode = query['hub.mode'];
const token = query['hub.verify_token'];
const challenge = query['hub.challenge'];

if (mode === 'subscribe' && token === verifyTokenEsperado && challenge) {
  return [{ json: { challenge: String(challenge), statusCode: 200 } }];
}
return [{ json: { challenge: 'Token de verificação inválido', statusCode: 403 } }];

// Extrai mensagens recebidas do WhatsApp Cloud API.
// Compatível com Webhook nativo do n8n: payload vem em $json.body.
// Também trata o evento de TESTE da Meta, que usa números e IDs fictícios.

const input = $input.first()?.json ?? {};
const payload = input.body ?? input;

const value =
  payload.entry?.[0]?.changes?.[0]?.value ??
  payload.value ??
  payload;

const changeField =
  payload.entry?.[0]?.changes?.[0]?.field ??
  '';

const message = value.messages?.[0];
const contact = value.contacts?.[0] ?? {};
const metadata = value.metadata ?? {};

if (!message) {
  return [];
}

const REAL_PHONE_NUMBER_ID = '1068905836312533';
const DISPLAY_PHONE_NUMBER = '+55 11 4224-0675';
const ADMIN_TEST_RECIPIENT = '5511993358259';

const messageId = message.id || '';
const originalFrom = String(message.from || contact.wa_id || '').replace(/\D/g, '');
const metaPhoneNumberId = String(metadata.phone_number_id || '');
const metaDisplayPhone = String(metadata.display_phone_number || '');

const isMetaTestPayload =
  metaPhoneNumberId === '123456123' ||
  metaDisplayPhone === '16505551111' ||
  originalFrom === '16315551181' ||
  String(payload.entry?.[0]?.id || '') === '0' ||
  String(messageId).startsWith('ABGG');

let from = originalFrom;
let phoneNumberId = metaPhoneNumberId || REAL_PHONE_NUMBER_ID;
let displayPhoneNumber = metaDisplayPhone || DISPLAY_PHONE_NUMBER;

if (isMetaTestPayload) {
  from = ADMIN_TEST_RECIPIENT;
  phoneNumberId = REAL_PHONE_NUMBER_ID;
  displayPhoneNumber = DISPLAY_PHONE_NUMBER;
}

const messageType = message.type || '';
const userName = contact.profile?.name || '';
let userMessage = '';

if (messageType === 'text') {
  userMessage = String(message.text?.body || '').trim();
}
if (messageType === 'button') {
  userMessage = String(message.button?.text || message.button?.payload || '').trim();
}
if (messageType === 'interactive') {
  userMessage = String(
    message.interactive?.button_reply?.title ||
    message.interactive?.button_reply?.id ||
    message.interactive?.list_reply?.title ||
    message.interactive?.list_reply?.id ||
    ''
  ).trim();
}
if (isMetaTestPayload && !userMessage) {
  userMessage = 'Olá, o que é o CECAPE?';
}
if (!isMetaTestPayload && messageType === 'text' && !userMessage) {
  return [];
}

if (!isMetaTestPayload) {
  const staticData = $getWorkflowStaticData('global');
  staticData.processedMessages = staticData.processedMessages || {};
  const dedupeKey = `${messageId}-${originalFrom}-${message.timestamp || ''}`;

  if (dedupeKey && staticData.processedMessages[dedupeKey]) return [];
  if (dedupeKey) staticData.processedMessages[dedupeKey] = new Date().toISOString();

  const keys = Object.keys(staticData.processedMessages);
  if (keys.length > 1000) {
    keys.slice(0, keys.length - 700).forEach(k => delete staticData.processedMessages[k]);
  }
}

if (!from) return [];
if (userMessage.length > 2500) userMessage = userMessage.slice(0, 2500);

// Captura media_id para os tipos que precisam de pré-processamento
// (áudio transcrito via Whisper, imagem descrita via Vision, vídeo com
// áudio extraído e transcrito). O texto definitivo (userMessage) só fica
// pronto depois desse pré-processamento, feito em nós seguintes.
const mediaId =
  message.audio?.id || message.image?.id || message.video?.id || '';
const mediaCaption = message.image?.caption || message.video?.caption || '';

return [{
  json: {
    from,
    originalFrom,
    userName,
    messageType,
    userMessage,
    messageId,
    phoneNumberId,
    displayPhoneNumber,
    changeField,
    isMetaTestPayload,
    mediaId,
    mediaCaption,
    respostaDeveSerAudio: messageType === 'audio',
    receivedAt: new Date().toISOString(),
    raw: value
  }
}];

// Restaura os dados originais e injeta o texto transcrito (áudio OU vídeo)
// como userMessage, fazendo a mensagem seguir o MESMO caminho de uma
// mensagem de texto normal. Se o vídeo veio com legenda (caption), ela é
// mantida junto, pois costuma conter a pergunta real do usuário.
const original = $('Extrair dados da mensagem').first().json;
const textoTranscrito = String($json.text || '').trim();
const caption = String(original.mediaCaption || '').trim();
const tipoOriginal = original.messageType; // 'audio' ou 'video'

let userMessage = textoTranscrito;
if (caption && textoTranscrito) {
  userMessage = `${caption}\n[transcrição do ${tipoOriginal === 'video' ? 'vídeo' : 'áudio'} enviado]: ${textoTranscrito}`;
} else if (caption) {
  userMessage = caption;
}

return [{
  json: {
    ...original,
    userMessage: userMessage || original.userMessage,
    messageType: 'text',
    messageTypeOriginal: tipoOriginal
  }
}];

