// Restaura os dados originais e injeta a descrição da imagem como userMessage.
// Se a imagem veio com legenda (caption), ela é mantida junto, pois costuma
// conter a pergunta real do usuário (ex: "isso aqui está certo?" + foto).
const original = $('Extrair dados da mensagem').first().json;
const descricaoImagem = String($json.choices?.[0]?.message?.content || '').trim();
const caption = String(original.mediaCaption || '').trim();

const userMessage = caption
  ? `${caption} [imagem enviada: ${descricaoImagem}]`
  : `[imagem enviada: ${descricaoImagem}]`;

return [{
  json: {
    ...original,
    userMessage,
    messageType: 'text',
    messageTypeOriginal: 'image'
  }
}];

// Configurações gerais do projeto.
// diagnosticMode = true: retorna a categoria técnica no WhatsApp para homologação.
// diagnosticMode = false: consulta Google Sheets e responde normalmente.

const diagnosticMode = false;
const spreadsheetId = '1NDC8stBwdhc0yUNZNWNiEKHTrDEq5chQqIRP0WAc2RQ';

const mensagens = {
  pergunta_vaga: 'Olá! Para te orientar melhor, sua dúvida é sobre cursos, certificados, inscrições, cronograma, acesso à plataforma ou suporte técnico?',
  fora_do_escopo: 'Desculpe, eu consigo responder apenas dúvidas relacionadas ao CECAPE, AutoriaSCS, cursos, formações, certificados, inscrições, cronogramas e orientações institucionais.',
  suporte_humano: 'Essa solicitação precisa de análise da equipe do CECAPE. Por favor, informe seu nome completo, unidade escolar, e-mail institucional e descreva brevemente o problema.',
  nao_suportado: 'Olá! No momento, este atendimento automático consegue responder apenas mensagens de texto. Por favor, envie sua dúvida por escrito sobre o CECAPE, AutoriaSCS, cursos, formações ou certificados.',
  sem_informacao: 'Desculpe, não encontrei essa informação na base oficial do CECAPE. Para melhor orientação, entre em contato com a equipe responsável.',
  erro_seguro: 'No momento, não consegui processar sua solicitação com segurança. Por favor, tente novamente em instantes ou entre em contato com a equipe responsável.'
};

const variacaoSeed = Math.random().toString(36).substring(2, 8);

// Período do dia, no horário de São Paulo, para saudações personalizadas.
const horaAgora = Number(new Date().toLocaleString('pt-BR', { timeZone: 'America/Sao_Paulo', hour: '2-digit', hour12: false }));
let periodoDoDia;
if (horaAgora >= 5 && horaAgora < 12) periodoDoDia = 'manha';
else if (horaAgora >= 12 && horaAgora < 18) periodoDoDia = 'tarde';
else periodoDoDia = 'noite';

return [{
  json: {
    ...$json,
    diagnosticMode,
    spreadsheetId,
    mensagens,
    modeloIA: 'gpt-4o-mini',
    variacaoSeed,
    periodoDoDia,
    limiteCaracteresResposta: 3500
  }
}];

// Faz o parse do JSON retornado pela IA classificadora e reconstrói o objeto
// 'master' no MESMO formato que o restante do workflow já espera, preservando
// 100% de compatibilidade com os nós seguintes (IF - Modo diagnóstico?, etc.)
const original = $('Montar histórico da conversa').first().json;

let classificacao;
try {
  classificacao = JSON.parse($json.choices?.[0]?.message?.content || '{}');
} catch (e) {
  classificacao = {};
}

const result = {
  categoria: classificacao.categoria || 'pergunta_vaga',
  agente_destino: classificacao.agente_destino || 'resposta_pergunta_vaga',
  confianca: typeof classificacao.confianca === 'number' ? classificacao.confianca : 0.55,
  dentro_escopo: classificacao.dentro_escopo !== undefined ? classificacao.dentro_escopo : true,
  precisa_humano: classificacao.precisa_humano || false,
  motivo: classificacao.motivo || 'Classificação via IA.',
  mensagem_reescrita: classificacao.mensagem_reescrita || original.userMessage,
  resposta_direta: classificacao.resposta_direta || ''
};

// Fallback de segurança: se a IA não devolver JSON válido nem categoria,
// usa pergunta_vaga com a mensagem fixa, para nunca travar o atendimento.
if (!classificacao.categoria) {
  result.resposta_direta = original.mensagens?.pergunta_vaga || result.resposta_direta;
}

return [{
  json: {
    ...original,
    master: result,
    categoria: result.categoria,
    agente_destino: result.agente_destino,
    confianca: result.confianca,
    dentro_escopo: result.dentro_escopo,
    precisa_humano: result.precisa_humano,
    resposta_direta: result.resposta_direta,
    nomeProprioMencionado: classificacao.nome_proprio_mencionado || null
  }
}];

const m = $json.master || {};
const resposta =
`[TESTE AGENTE MASTER]

Categoria: ${m.categoria}
Agente destino: ${m.agente_destino}
Confiança: ${m.confianca}
Dentro do escopo: ${m.dentro_escopo ? 'sim' : 'não'}
Precisa humano: ${m.precisa_humano ? 'sim' : 'não'}
Motivo: ${m.motivo}
Mensagem reescrita: ${m.mensagem_reescrita || ''}`;
return [{ json: { ...$json, to: $json.from, resposta } }];

// Mantém a mensagem base para o WhatsApp.
// A variação de linguagem vem do nó IA Resposta Direta logo abaixo.
let resposta = $json.resposta_direta || $json.mensagens.erro_seguro;

// Se a mensagem foi uma imagem, garante que a resposta reconheça o que foi
// recebido (a descrição gerada pelo Vision está dentro de [imagem enviada: ...]).
// Feito em código porque o classificador nem sempre segue a instrução do prompt
// e devolvia apenas a mensagem fixa ("não posso ajudar") ignorando a imagem.
const marcador = String($json.userMessage || '').match(/\[imagem enviada: ([\s\S]+?)\]/);
const jaMencionaImagem = /imagem|foto/i.test(resposta);
if (marcador && !jaMencionaImagem) {
  let descricao = marcador[1].trim().replace(/\s+/g, ' ');
  if (descricao.length > 200) descricao = descricao.slice(0, 200).trim() + '...';
  resposta = `Recebi sua imagem. O que identifiquei nela: ${descricao} ` + resposta;
}

return [{
  json: {
    ...$json,
    to: $json.from,
    resposta,
    resposta_direta_base: resposta
  }
}];

// Define qual aba da planilha oficial deve ser consultada.

const categoria = $json.categoria || '';

const mapaAbas = {
  institucional_cecape: 'INSTITUCIONAL_CECAPE',
  autoriascs_plataforma: 'AUTORIASCS_PLATAFORMA',
  cursos_formacoes: 'CURSOS_FORMACOES',
  agenda_cronograma: 'AGENDA_CRONOGRAMA',
  certificados: 'CERTIFICADOS',
  inscricoes: 'INSCRICOES',
  corpo_docente: 'FORMADORES', // não usado na prática: corpo_docente sempre é desviado antes deste mapa, ver IF - É categoria corpo docente?
  ferramentas_produtos: 'FERRAMENTAS_PRODUTOS',
  suporte_humano: 'SUPORTE_ENCAMINHAMENTO',
  fora_do_escopo: 'FALLBACKS',
  pergunta_vaga: 'FALLBACKS'
};

const nomesAgentes = {
  institucional_cecape: 'Agente Institucional CECAPE',
  autoriascs_plataforma: 'Agente AutoriaSCS / Plataforma EAD',
  cursos_formacoes: 'Agente de Cursos e Formações',
  agenda_cronograma: 'Agente de Agenda e Cronogramas',
  certificados: 'Agente de Certificados',
  inscricoes: 'Agente de Inscrições',
  corpo_docente: 'Agente de Corpo Docente',
  ferramentas_produtos: 'Agente de Ferramentas e Produtos',
  suporte_humano: 'Agente de Suporte Humano'
};

return [{
  json: {
    ...$json,
    nomeAba: mapaAbas[categoria] || 'INSTITUCIONAL_CECAPE',
    nomeAgenteEspecialista: nomesAgentes[categoria] || 'Agente Especialista CECAPE'
  }
}];

// Recebe linhas do Google Sheets e monta o contexto oficial.
// Usa apenas linhas com ativo = Sim, quando a coluna existir.

function normalize(str) {
  return String(str ?? '')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .trim();
}

function isActive(row) {
  const ativo = row.ativo ?? row.Ativo ?? row.ATIVO;
  if (ativo === undefined || ativo === null || String(ativo).trim() === '') return true;
  return ['sim', 's', 'ativo', 'true', '1', 'yes'].includes(normalize(ativo));
}

const original = $('Mapear aba da base oficial').first().json;
const rows = $input.all().map(item => item.json || {}).filter(row => Object.keys(row).length > 0);
const activeRows = rows.filter(isActive);

function rowToText(row, index) {
  const lines = Object.entries(row)
    .filter(([key, value]) => value !== undefined && value !== null && String(value).trim() !== '')
    .map(([key, value]) => `${key}: ${String(value).trim()}`);
  return `Registro ${index + 1}:\n${lines.join('\n')}`;
}

let contextoOficial = activeRows.map(rowToText).join('\n\n---\n\n');

if (!contextoOficial) {
  contextoOficial = `Nenhum registro ativo encontrado na aba ${original.nomeAba}.`;
}

if (contextoOficial.length > 30000) {
  contextoOficial = contextoOficial.slice(0, 30000) + '\n\n[Contexto reduzido automaticamente por limite de tamanho.]';
}

return [{
  json: {
    ...original,
    quantidadeRegistrosLidos: rows.length,
    quantidadeRegistrosAtivos: activeRows.length,
    contextoOficial
  }
}];

