const original = $('Unificar contexto (cursos ou base oficial)').first().json;

let resposta =
  $json.choices?.[0]?.message?.content ??
  $json.output ??
  $json.text ??
  '';

resposta = String(resposta || '')
  .replace(/\r/g, '')
  .replace(/\n{3,}/g, '\n\n')
  .trim();

if (!resposta) {
  resposta = original.mensagens?.erro_seguro || 'No momento, não consegui processar sua solicitação com segurança.';
}

// Validação anti-alucinação de links: todo link mencionado pela IA precisa existir
// literalmente no contexto oficial. Se um link foi inventado/alterado, ele é removido
// e avisamos no log interno (não exposto ao usuário) para acompanhamento.
const contextoOficial = String(original.contextoOficial || '');

// Extrai URLs tanto em markdown [texto](url) quanto soltas no texto.
const linksMarkdown = [...resposta.matchAll(/\]\((https?:\/\/[^)]+)\)/g)].map(m => m[1]);
const linksSoltos = resposta.match(/(?<!\]\()https?:\/\/[^\s)]+/g) || [];
const linksNaResposta = [...new Set([...linksMarkdown, ...linksSoltos])];

const linksInventados = [];
const linksValidados = [];

for (const link of linksNaResposta) {
  const linkLimpo = link.replace(/[.,;!?]+$/, ''); // remove pontuação final colada
  if (contextoOficial.includes(linkLimpo)) {
    linksValidados.push(linkLimpo);
  } else {
    linksInventados.push(linkLimpo);
    resposta = resposta.split(link).join('[link indisponível - confirme com a equipe]');
  }
}

const limite = Number(original.limiteCaracteresResposta || 900);
if (resposta.length > limite) {
  resposta = resposta.slice(0, limite).trim() + '...';
}

return [{
  json: {
    ...original,
    to: original.from,
    resposta,
    linksInventadosDetectados: linksInventados,
    linksValidadosOk: linksValidados,
    tamanhoContextoOficial: contextoOficial.length
  }
}];

