// CRM: consolida o registro da mensagem depois do envio da resposta.
// Atualiza a MESMA linha criada na entrada (match por id_mensagem) com a
// resposta enviada, categoria, formato, tempos e status "Respondida".
const entrada = $('Extrair dados da mensagem').first().json;
const d = $json;

const agora = new Date();
const recebidaEm = entrada.receivedAt ? new Date(entrada.receivedAt) : null;
const tempoRespostaSegundos = (recebidaEm && !isNaN(recebidaEm))
  ? Math.round((agora.getTime() - recebidaEm.getTime()) / 1000)
  : '';

const formatoResposta = d.ttsFalhou
  ? 'texto (fallback TTS)'
  : (d.respostaDeveSerAudio ? 'áudio' : 'texto');

const tipoLabel = {
  text: 'texto', audio: 'áudio', image: 'imagem', video: 'vídeo',
  button: 'botão', interactive: 'interativo', document: 'documento', sticker: 'figurinha'
};

return [{
  json: {
    id_mensagem: entrada.messageId || '',
    timestamp_recebida: entrada.receivedAt || '',
    data_hora: agora.toLocaleString('pt-BR', { timeZone: 'America/Sao_Paulo' }),
    numero_usuario: d.to || d.from || entrada.from || '',
    nome_usuario: d.nomeSalvo || d.userName || entrada.userName || '',
    formato_recebido: tipoLabel[entrada.messageType] || entrada.messageType || '',
    mensagem_recebida: d.userMessage || entrada.userMessage || '',
    categoria_identificada: d.categoria || d.master?.categoria || '',
    agente_acionado: d.agente_destino || d.master?.agente_destino || '',
    resposta_enviada: d.resposta || '',
    formato_resposta: formatoResposta,
    timestamp_resposta: agora.toISOString(),
    tempo_resposta_segundos: String(tempoRespostaSegundos),
    status: 'Respondida',
    erro: (d.linksInventadosDetectados && d.linksInventadosDetectados.length > 0)
      ? `Links inventados removidos (contexto: ${d.tamanhoContextoOficial || 0} chars): ${d.linksInventadosDetectados.join(', ')}`
      : '',
    encaminhamento_humano: (d.precisa_humano || d.master?.precisa_humano) ? 'Sim' : 'Não'
  }
}];

// Calcula a lista de meses a consultar: do mês seguinte ao atual até dezembro.
// Cada item gerado vira uma execução separada do node de leitura do Google Sheets.
// Abas no formato: JANEIRO, FEVEREIRO, MARÇO, ... (maiúsculas, com acento)

const meses = [
  'JANEIRO', 'FEVEREIRO', 'MARÇO', 'ABRIL', 'MAIO', 'JUNHO',
  'JULHO', 'AGOSTO', 'SETEMBRO', 'OUTUBRO', 'NOVEMBRO', 'DEZEMBRO'
];

const hoje = new Date();
const indiceMesAtual = hoje.getMonth(); // 0 = janeiro ... 11 = dezembro
const indiceProximoMes = indiceMesAtual + 1; // primeiro mês a consultar

const mesesAConsultar = [];
for (let i = indiceProximoMes; i <= 11; i++) {
  mesesAConsultar.push(meses[i]);
}

// Se já estamos em dezembro, não há mês seguinte dentro do mesmo ano.
// Nesse caso, mantém ao menos o mês atual como fallback para não ficar sem nada.
if (mesesAConsultar.length === 0) {
  mesesAConsultar.push(meses[indiceMesAtual]);
}

// Gera um item por mês a consultar, preservando todos os dados originais em cada um.
return mesesAConsultar.map(nomeMes => ({
  json: {
    ...$json,
    nomeAbaCursos: nomeMes
  }
}));

// Monta o contexto oficial de cursos a partir da planilha de Cursos Abertos.
// Agora consulta TODOS os meses do mês seguinte até dezembro (múltiplos meses por execução).
// Filtra por DIVULGAR = Sim (quando a coluna existir) e remove e-mails da coluna FORMADORES.
// A coluna DIVULGAR nunca é exibida ao usuário.
// Inclui o LINK_INSCRICAO de cada curso (ainda fictício, até existir coluna própria na planilha).

function normalize(str) {
  return String(str ?? '')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .trim();
}

function deveDivulgar(row) {
  const divulgar = row['DIVULGAR'] ?? row['Divulgar'] ?? row['divulgar'];
  if (divulgar === undefined || divulgar === null || String(divulgar).trim() === '') return true;
  return ['sim', 's', 'true', '1', 'yes'].includes(normalize(divulgar));
}

function limparFormadores(valor) {
  if (!valor) return '';
  return String(valor)
    .split(/[,;\n]/)
    .map(parte => parte.replace(/\S+@\S+/g, '').trim())
    .filter(Boolean)
    .join(', ');
}

function gerarLinkInscricaoFicticio(idCurso) {
  // Link fictício, apenas para visualizar como ficará na mensagem.
  // Quando a planilha tiver uma coluna real de link, substituir esta função.
  return `https://inscricoes.cecape.org.br/curso/${idCurso}`;
}

// Dados originais (categoria, mensagens, etc.) vêm de antes do branch de meses.
const original = $('Calcular mês seguinte').first().json;

// Itens de entrada: cada um é uma linha de curso, vinda de algum dos meses consultados.
// O node de leitura roda uma vez por mês (um item de entrada = um mês), então usamos
// o índice de execução (pairedItem) para recuperar de qual mês cada linha veio.
const itensEntrada = $input.all();
const mesesConsultados = $('Calcular mês seguinte').all().map(item => item.json.nomeAbaCursos);

const linhasComMes = itensEntrada.map(item => {
  const row = item.json || {};
  let nomeMesOrigem = '';
  try {
    const indiceOrigem = item.pairedItem?.item ?? item.pairedItem?.[0]?.item;
    nomeMesOrigem = mesesConsultados[indiceOrigem] || '';
  } catch (e) {
    nomeMesOrigem = '';
  }
  return { row, nomeMesOrigem };
});

const linhasValidas = linhasComMes.filter(({ row }) => row && Object.keys(row).length > 0);
const cursosDivulgaveis = linhasValidas.filter(({ row }) => deveDivulgar(row));

const colunasExibidas = [
  'DATA', 'INÍCIO', 'TÉRMINO', 'DIA DA SEMANA', 'ESPAÇO',
  'FORMADORES', 'TÍTULO', 'ETAPAS', 'COMPONENTE CURRICULAR',
  'PÚBLICO-ALVO', 'FORMATO', 'VAGAS', 'GOOGLE SALA DE AULA'
];

function rowToText({ row, nomeMesOrigem }, index) {
  const linhas = colunasExibidas
    .map(coluna => {
      let valor = row[coluna];
      if (coluna === 'FORMADORES') valor = limparFormadores(valor);
      if (valor === undefined || valor === null || String(valor).trim() === '') return null;
      return `${coluna}: ${String(valor).trim()}`;
    })
    .filter(Boolean);

  const idCurso = `${(nomeMesOrigem || 'curso').toLowerCase()}-${index + 1}`;
  const linkInscricao = gerarLinkInscricaoFicticio(idCurso);

  return `Curso ${index + 1} (Mês: ${nomeMesOrigem || 'não identificado'}):\n${linhas.join('\n')}\nLink de inscrição: ${linkInscricao}`;
}

let contextoCursos = cursosDivulgaveis.map(rowToText).join('\n\n---\n\n');

if (!contextoCursos) {
  contextoCursos = `Nenhum curso encontrado entre os meses consultados (${mesesConsultados.join(', ')}).`;
}

if (contextoCursos.length > 12000) {
  contextoCursos = contextoCursos.slice(0, 12000) + '\n\n[Contexto reduzido automaticamente por limite de tamanho.]';
}

return [{
  json: {
    ...original,
    nomeAba: `CURSOS (${mesesConsultados.join(', ')})`,
    quantidadeRegistrosLidos: linhasValidas.length,
    quantidadeRegistrosAtivos: cursosDivulgaveis.length,
    contextoOficial: contextoCursos
  }
}];

// Monta um histórico curto da conversa com o mesmo número,
// usando o LOG_ATENDIMENTOS como memória de curto prazo.
// Considera apenas mensagens dos últimos 30 minutos e no máximo as últimas 4 trocas.

const original = $('CONFIG - Agente Master').first().json;
const numeroAtual = String(original.from || '').replace(/\D/g, '');

const JANELA_MINUTOS = 30;
const MAX_TROCAS = 4;

function parseDataHoraBR(str) {
  // Formato salvo: "dd/mm/aaaa, hh:mm:ss" (pt-BR, America/Sao_Paulo)
  const m = String(str || '').match(/(\d{2})\/(\d{2})\/(\d{4}),?\s*(\d{2}):(\d{2}):(\d{2})/);
  if (!m) return null;
  const [, dia, mes, ano, h, min, seg] = m;
  return new Date(`${ano}-${mes}-${dia}T${h}:${min}:${seg}`);
}

const linhas = $input.all().map(item => item.json || {});

const agora = new Date();
const limiteJanela = new Date(agora.getTime() - JANELA_MINUTOS * 60 * 1000);

const doMesmoNumero = linhas.filter(linha => {
  const numeroLinha = String(linha.numero_usuario || '').replace(/\D/g, '');
  // CRM v3.5: a mensagem atual já foi registrada na entrada (status Recebida),
  // então precisa ser excluída do histórico; linhas ainda sem resposta também.
  const ehMensagemAtual = String(linha.id_mensagem || '') === String(original.messageId || '');
  const temResposta = String(linha.resposta_enviada || '').trim().length > 0;
  return numeroLinha && numeroLinha === numeroAtual && !ehMensagemAtual && temResposta;
});

const recentes = doMesmoNumero.filter(linha => {
  const dataHora = parseDataHoraBR(linha.data_hora);
  return dataHora && dataHora >= limiteJanela;
});

const ultimasTrocas = recentes.slice(-MAX_TROCAS);

let historicoConversa = '';
if (ultimasTrocas.length > 0) {
  historicoConversa = ultimasTrocas
    .map((linha, i) => {
      const pergunta = String(linha.mensagem_recebida || '').trim();
      const resposta = String(linha.resposta_enviada || '').trim();
      return `[Troca ${i + 1}]\nUsuário: ${pergunta}\nAgente: ${resposta}`;
    })
    .join('\n\n');
} else {
  historicoConversa = '(Nenhuma conversa recente com este usuário. Trate como primeira mensagem.)';
}

const ultimaCategoria = ultimasTrocas.length > 0
  ? (ultimasTrocas[ultimasTrocas.length - 1].categoria_identificada || '')
  : '';

return [{
  json: {
    ...original,
    historicoConversa,
    ultimaCategoriaConversa: ultimaCategoria
  }
}];

