parameters.jsCode:
// Usa a resposta variada da IA; se falhar, usa a mensagem base fixa como fallback.
// Importante: os dados originais (to, mensagens, etc.) vêm de "Preparar resposta direta",
// não do retorno da OpenAI (que só tem choices/usage/model).
const original = $('Preparar resposta direta').first().json;

let respostaVariada =
  $json.choices?.[0]?.message?.content ??
  '';

respostaVariada = String(respostaVariada || '')
  .replace(/\r/g, '')
  .replace(/\n{3,}/g, '\n\n')
  .trim();

const respostaFinal = respostaVariada || original.resposta_direta_base || original.mensagens?.erro_seguro || '';

return [{
  json: {
    ...original,
    resposta: respostaFinal
  }
}];

// Verifica se o número já existe na aba CONTATOS.
// Define se é um contato novo (precisa se apresentar e perguntar o nome)
// ou um contato conhecido (usa o nome salvo, sem perguntar de novo).

// A mensagem pode ter chegado como áudio/vídeo/imagem: nesse caso o texto
// definitivo (transcrição/descrição) está no nó conversor, não na extração.
let original = $('Extrair dados da mensagem').first().json;
for (const nomeNo of ['Converter transcrição em texto', 'Converter imagem em texto']) {
  try {
    const convertido = $(nomeNo).first().json;
    if (convertido && convertido.userMessage) { original = convertido; break; }
  } catch (e) { /* nó não executou nesta execução (mensagem não era desse tipo) */ }
}
const numeroAtual = String(original.from || '').replace(/\D/g, '');

// Filtra itens vazios (caso a planilha CONTATOS ainda não tenha registros
// e o node de leitura tenha retornado um item vazio via alwaysOutputData).
const linhas = $input.all()
  .map(item => item.json || {})
  .filter(linha => linha && Object.keys(linha).length > 0 && linha.numero);

const contatoExistente = linhas.find(linha => {
  const numeroLinha = String(linha.numero || '').replace(/\D/g, '');
  return numeroLinha && numeroLinha === numeroAtual;
});

const ehContatoNovo = !contatoExistente;
const nomeSalvo = contatoExistente?.nome ? String(contatoExistente.nome).trim() : '';
const jaApresentado = contatoExistente?.apresentado
  ? ['sim', 's', 'true', '1'].includes(String(contatoExistente.apresentado).toLowerCase().trim())
  : false;

// Tenta capturar um nome se a pessoa respondeu à pergunta "qual é o seu nome?"
// (heurística simples: contato é novo, já foi apresentado antes mas ainda sem nome salvo,
// e a mensagem atual parece ser só um nome — curta, sem números, sem pontuação de pergunta)
const mensagemAtual = String(original.userMessage || '').trim();
const pareceSerNome = mensagemAtual.length > 0 && mensagemAtual.length <= 60 &&
  !/[0-9?]/.test(mensagemAtual) &&
  mensagemAtual.split(' ').length <= 5;

const precisaPerguntarNome = ehContatoNovo || (!nomeSalvo && jaApresentado === false);
const respondendoNome = !ehContatoNovo && !nomeSalvo && jaApresentado && pareceSerNome;

const primeiroContatoSalvo = contatoExistente?.primeiro_contato || '';

return [{
  json: {
    ...original,
    ehContatoNovo,
    nomeSalvo,
    jaApresentado,
    precisaPerguntarNome,
    respondendoNome,
    primeiro_contato: primeiroContatoSalvo
  }
}];

// Mensagem de apresentação para contatos novos, pedindo o nome.
// É uma mensagem fixa (sem IA) para garantir consistência institucional.

return [{
  json: {
    ...$json,
    to: $json.from,
    resposta: 'Olá! 👋 Eu sou o Comunicador Oficial do CECAPE IA, o assistente virtual do Centro de Capacitação dos Profissionais da Educação.\n\nAntes de começarmos, qual é o seu nome?'
  }
}];

// Confirma o nome recebido e explica brevemente o que o assistente pode fazer.
// Mensagem fixa, sem IA, para garantir consistência.

const primeiroNome = String($json.userMessage || '').trim().split(' ')[0];

return [{
  json: {
    ...$json,
    to: $json.from,
    resposta: `Prazer, ${primeiroNome}! 😊 Estou aqui para te ajudar com dúvidas sobre cursos, certificados, inscrições, cronograma, acesso à plataforma ou suporte técnico do CECAPE. Pode me perguntar!`
  }
}];

// O node anterior (Google Sheets - Salvar contato) substitui o $json
// pelo retorno da escrita na planilha, perdendo userMessage, categoria, etc.
// Aqui restauramos todos os dados originais calculados em "Identificar contato".

const original = $('Identificar contato').first().json;

return [{
  json: {
    ...original
  }
}];

// Monta o contexto de corpo docente a partir das 6 abas permitidas
// (INFANTIL, INICIAIS, FINAIS, PROJETOS, GESTÃO, Direção), cada uma lida por um node
// fixo e dedicado (evita o bug do node Google Sheets com sheetName dinâmico
// repetindo o mesmo conjunto de linhas para todos os itens de entrada).
//
// O cabeçalho real da coluna de nomes varia por aba (ex: "FORMADORES • EDUCAÇÃO
// INFANTIL"), então pegamos sempre o primeiro valor textual de cada linha
// (coluna A) como nome, e o segundo valor (coluna B) como e-mail.
// E-mails agora SÃO incluídos no contexto (liberado a pedido do usuário) —
// a IA decide se exibe ou não, conforme o que foi perguntado.

const original = $('IF - É categoria corpo docente?').first().json;

const mapaAreaNode = {
  'INFANTIL': 'GSheets - Docente INFANTIL',
  'INICIAIS': 'GSheets - Docente INICIAIS',
  'FINAIS': 'GSheets - Docente FINAIS',
  'PROJETOS': 'GSheets - Docente PROJETOS',
  'GESTÃO': 'GSheets - Docente GESTÃO',
  'DIREÇÃO': 'GSheets - Docente DIREÇÃO'
};

function extrairPessoas(nomeNode) {
  const linhas = $(nomeNode).all().map(item => item.json || {});
  const pessoas = [];
  for (const row of linhas) {
    if (Object.keys(row).length === 0) continue;
    const valores = Object.values(row).filter(v => typeof v !== 'number');
    let nome = String(valores[0] || '').trim();
    let email = String(valores[1] || '').trim();

    const pareceCabecalhoOuLixo = !nome || nome.includes('@') || nome.toUpperCase() === 'NOME';
    if (pareceCabecalhoOuLixo) continue;

    pessoas.push({ nome, email });
  }
  return pessoas;
}

const pessoasPorArea = {};
for (const [area, nomeNode] of Object.entries(mapaAreaNode)) {
  pessoasPorArea[area] = extrairPessoas(nomeNode);
}

const totalGeral = Object.values(pessoasPorArea).reduce((acc, arr) => acc + arr.length, 0);

const blocos = Object.entries(pessoasPorArea)
  .map(([area, pessoas]) => {
    const linhasPessoas = pessoas.length > 0
      ? pessoas.map(p => `- ${p.nome}${p.email ? ' | e-mail: ' + p.email : ''}`).join('\n')
      : '(nenhum nome encontrado)';
    return `Área: ${area} (${pessoas.length} pessoa${pessoas.length !== 1 ? 's' : ''})\n${linhasPessoas}`;
  });

let contextoDocente = `TOTAL GERAL DE PESSOAS CADASTRADAS (formadores, professores, gestão e direção): ${totalGeral}\n\n` + blocos.join('\n\n---\n\n');

return [{
  json: {
    ...original,
    nomeAba: `CORPO DOCENTE (${Object.keys(mapaAreaNode).join(', ')})`,
    contextoOficial: contextoDocente,
    quantidadeRegistrosLidos: totalGeral,
    quantidadeRegistrosAtivos: totalGeral
  }
}];

// O node anterior substitui o $json pelo retorno da API do WhatsApp,
// perdendo userMessage, categoria, etc. Restauramos os dados originais
// lendo o nó "Wait - Anti-spam 2s" (saída única, executa em todos os
// caminhos). NUNCA ler "Switch - Formato de resposta" aqui: em nós de
// múltiplas saídas, $('...').first() só enxerga a primeira saída e
// quebra quando a resposta sai pela saída de texto (fallback).
const original = $('Wait - Anti-spam 2s').first().json;

// Se o TTS falhou e a resposta caiu no fallback de texto, registra isso
// para o CRM logar o formato correto ("texto (fallback TTS)").
let ttsFalhou = false;
try {
  ttsFalhou = $('Fallback TTS - Enviar texto').first().json.ttsFalhou === true;
} catch (e) { /* fallback não executou nesta execução */ }

return [{ json: { ...original, ttsFalhou } }];

// Garante que o arquivo binário tenha nome/extensão compatíveis com a API
// Whisper da OpenAI, que detecta o formato pela extensão do nome do arquivo.
// Mensagens de voz do WhatsApp chegam como audio/ogg (opus); vídeos como video/mp4.
const item = $input.first();
const bin = item.binary?.data;
if (!bin) throw new Error('Nenhum arquivo de mídia recebido para transcrição.');

const mime = String(bin.mimeType || '').toLowerCase();
let ext = 'ogg';
if (mime.includes('mpeg') || mime.includes('mp3')) ext = 'mp3';
else if (mime.startsWith('video/mp4')) ext = 'mp4';
else if (mime.includes('mp4') || mime.includes('m4a')) ext = 'm4a';
else if (mime.includes('webm')) ext = 'webm';
else if (mime.includes('wav')) ext = 'wav';

bin.fileName = `midia-whatsapp.${ext}`;
return [{ json: item.json, binary: item.binary }];

// Converte o binário da imagem baixada em data URI base64,
// formato aceito pela API de visão da OpenAI (a URL de mídia do WhatsApp
// exige autenticação, então não pode ser passada diretamente à OpenAI).
const item = $input.first();
const buffer = await this.helpers.getBinaryDataBuffer(0, 'data');
if (!buffer || buffer.length === 0) throw new Error('Imagem baixada está vazia.');
if (buffer.length > 15 * 1024 * 1024) throw new Error('Imagem muito grande para análise.');

const mimeType = item.binary?.data?.mimeType || 'image/jpeg';
return [{ json: { imageDataUri: `data:${mimeType};base64,${buffer.toString('base64')}` } }];

// O nó de TTS devolve apenas o binário do áudio; aqui restauramos os dados
// (to, phoneNumberId, resposta etc.) que estavam no item antes do TTS,
// mantendo o binário para o envio via WhatsApp.
const original = $('Wait - Anti-spam 2s').first().json;
const binario = $input.first().binary;
if (!binario?.data) throw new Error('TTS não retornou áudio.');
return [{ json: { ...original }, binary: binario }];

// Se a geração do áudio (TTS) falhar por qualquer motivo, garante que o
// usuário receba a resposta em texto em vez de ficar sem retorno.
const original = $('Wait - Anti-spam 2s').first().json;
return [{ json: { ...original, respostaDeveSerAudio: false, ttsFalhou: true } }];

// CRM: registra imediatamente cada mensagem recebida na aba LOG_ATENDIMENTOS,
// ANTES de qualquer processamento (IA, mídia, envio). Assim nenhuma solicitação
// se perde: se o fluxo falhar depois, a linha permanece com status "Recebida"
// (ou "Erro") e a equipe consegue ver o que ficou sem resposta.
const d = $json;

const tipoLabel = {
  text: 'texto', audio: 'áudio', image: 'imagem', video: 'vídeo',
  button: 'botão', interactive: 'interativo', document: 'documento', sticker: 'figurinha'
};
const placeholder = {
  audio: '[áudio recebido - transcrição em processamento]',
  image: '[imagem recebida - análise em processamento]',
  video: '[vídeo recebido - transcrição em processamento]'
};

return [{
  json: {
    id_mensagem: d.messageId || `${d.from || 'desconhecido'}-${Date.now()}`,
    timestamp_recebida: d.receivedAt || new Date().toISOString(),
    data_hora: new Date().toLocaleString('pt-BR', { timeZone: 'America/Sao_Paulo' }),
    numero_usuario: d.from || '',
    nome_usuario: d.userName || '',
    formato_recebido: tipoLabel[d.messageType] || d.messageType || '',
    mensagem_recebida: d.userMessage || placeholder[d.messageType] || `[mensagem do tipo "${d.messageType}"]`,
    status: 'Recebida'
  }
}];

// CRM: captura falhas das etapas críticas (IA, mídia, envio WhatsApp) e
// atualiza a linha da mensagem para status "Erro", com o nó e o motivo.
// Sem isso, execuções com falha desaparecem sem deixar rastro na planilha.
let entrada = {};
try { entrada = $('Extrair dados da mensagem').first().json; } catch (e) { /* extração não rodou */ }

const err = $json.error || {};
const descricao = [err.name, err.message || $json.message]
  .filter(Boolean).join(': ') || 'Erro não identificado';
let noOrigem = '';
try { noOrigem = $prevNode.name; } catch (e) { /* indisponível */ }

return [{
  json: {
    id_mensagem: entrada.messageId || `${entrada.from || 'desconhecido'}-${Date.now()}`,
    timestamp_recebida: entrada.receivedAt || '',
    data_hora: new Date().toLocaleString('pt-BR', { timeZone: 'America/Sao_Paulo' }),
    numero_usuario: entrada.from || '',
    nome_usuario: entrada.userName || '',
    mensagem_recebida: entrada.userMessage || '',
    status: 'Erro',
    erro: `[${noOrigem}] ${String(descricao).slice(0, 500)}`
  }
}];

// CRM: uma gravação na planilha falhou (mesmo após 3 tentativas).
// Monta um alerta com o erro exato e envia por WhatsApp ao administrador,
// para que "planilha não atualiza" nunca seja silencioso.
let origem = '';
try { origem = $prevNode.name; } catch (e) { /* indisponível */ }

const err = $json.error || {};
const detalhe = [err.name, err.message || $json.message]
  .filter(Boolean).join(': ') || JSON.stringify($json).slice(0, 300);

let entrada = {};
try { entrada = $('Extrair dados da mensagem').first().json; } catch (e) { /* extração não rodou */ }

const texto =
`⚠️ CRM CECAPE - FALHA AO GRAVAR NA PLANILHA

Nó: ${origem}
Erro: ${String(detalhe).slice(0, 400)}

Mensagem de: ${entrada.from || '?'} ${entrada.userName ? '(' + entrada.userName + ')' : ''}
Texto: ${String(entrada.userMessage || '').slice(0, 200)}

Verifique, nesta ordem:
1. A aba LOG_ATENDIMENTOS tem a coluna id_mensagem? (rode setupCRM no Apps Script)
2. A credencial Google Sheets está válida?
3. O ID da planilha no workflow é o da planilha correta?`;

return [{
  json: {
    to: '5511993358259',
    phoneNumberId: entrada.phoneNumberId || '1068905836312533',
    resposta: texto
  }
}];
